#!/bin/sh# verify_v3_wiring.sh - 15 on-chain verification checks for P1 AS2_* wiring (v3.0.0)set -euSDK="--sdk-conf-path=/work/sdk_config.yml --chain-id=chain1 --org-id=wx-org.chainmaker.org"TLS="--user-tlscrt-file-path=/work/admin1.tls.crt --user-tlskey-file-path=/work/admin1.tls.key --user-signcrt-file-path=/work/admin1.sign.crt --user-signkey-file-path=/work/admin1.sign.key"GET_FLAGS="$SDK $TLS --result-to-string"STAKING=95f2f001a4f65e8652bbdae34487ed9596fe19e7REGISTRY=4f60b9d9e3bc739e619757e43ca699d3ada3c2a6ATTRIBUTION=9e49c41b5ca66afb3088445a182601133b3e6987GOVERNANCE=106d3686d2492ce75d1e4a01e799d22e7d2c9e74SSE=9c755215c30c88a84930b09ef5112797a19134feBADGES=5b0627af6bc4da42f460289d3b535700e0d3af75q() { # $1=contract-name $2=addr $3=abi $4=method $5=params  cmc client contract user get --contract-name=$1 --contract-address=$2 \    --method=$4 --abi-file-path=$3 $GET_FLAGS --params="$5" 2>&1}echo "=== 1/15 StakingManager.governance (expect $GOVERNANCE) ==="q AS_Staking $STAKING /work/StakingManager.abi governance '[]'echo "=== 2/15 StakingManager.reputationOracle (expect $SSE) ==="q AS_Staking $STAKING /work/StakingManager.abi reputationOracle '[]'echo "=== 3/15 StakingManager.authorizedCallers[AS2_SkillRegistry] (expect true) ==="q AS_Staking $STAKING /work/StakingManager.abi authorizedCallers '[{"address":"0x'"$REGISTRY"'"}]'echo "=== 4/15 StakingManager.authorizedCallers[Attribution] (expect true) ==="q AS_Staking $STAKING /work/StakingManager.abi authorizedCallers '[{"address":"0x'"$ATTRIBUTION"'"}]'echo "=== 5/15 Attribution.stakingManager (expect $STAKING) ==="q AS_Attribution $ATTRIBUTION /work/Attribution.abi stakingManager '[]'echo "=== 6/15 AS2_SSE.stakingManager (expect $STAKING) ==="q AS2_SSE $SSE /work/SelfSustainingEcosystem.abi stakingManager '[]'echo "=== 7/15 AS2_SSE.skillRegistry (expect $REGISTRY) ==="q AS2_SSE $SSE /work/SelfSustainingEcosystem.abi skillRegistry '[]'echo "=== 8/15 AS2_SSE.attribution (expect $ATTRIBUTION) ==="q AS2_SSE $SSE /work/SelfSustainingEcosystem.abi attribution '[]'echo "=== 9/15 AS2_SSE.governance (expect $GOVERNANCE) ==="q AS2_SSE $SSE /work/SelfSustainingEcosystem.abi governance '[]'echo "=== 10/15 AS2_SSE.reputationBadges (expect $BADGES) ==="q AS2_SSE $SSE /work/SelfSustainingEcosystem.abi reputationBadges '[]'echo "=== 11/15 AS2_SSE.reputationBadgesSet (expect true) ==="q AS2_SSE $SSE /work/SelfSustainingEcosystem.abi reputationBadgesSet '[]'echo "=== 12/15 ReputationBadges.issuer (expect $SSE) ==="q ReputationBadges $BADGES /work/ReputationBadges.abi issuer '[]'echo "=== 13/15 Governance.stakingManager (expect $STAKING) ==="q DaoGovernance $GOVERNANCE /work/Governance.abi stakingManager '[]'echo "=== 14/15 AS2_SkillRegistry.stakingManager (expect $STAKING, ctor-set) ==="q AS2_SkillRegistry $REGISTRY /work/SkillRegistry.abi stakingManager '[]'echo "=== 15/15 AS2_SkillRegistry.nextSkillId (expect >= 1) ==="q AS2_SkillRegistry $REGISTRY /work/SkillRegistry.abi nextSkillId '[]'echo "=== ALL 15 VERIFICATION CHECKS DONE ==="